import React, { useState, useEffect, useContext } from "react";
import jsPDF from "jspdf";
import "jspdf-autotable";
import axios from "axios";
import { motion, AnimatePresence } from "framer-motion";
import { Link, useNavigate } from "react-router-dom";
import SearchBar from "./SearchBar";
import { OrderContext } from "./OrderContext";

const AllOrders = () => {
    const [orders, setOrders] = useState([]);
    const [showAlert, setShowAlert] = useState(false);
    const [alertMessage, setAlertMessage] = useState("");
    const [showConfirmDialog, setShowConfirmDialog] = useState(false);
    const [confirmDialogData, setConfirmDialogData] = useState(null);
    const [searchQuery, setSearchQuery] = useState("");
    const [loading, setLoading] = useState(true);

    const navigate = useNavigate();
    const { ordersChanged } = useContext(OrderContext);

    const fetchOrders = async () => {
        try {
            setLoading(true);
            const res = await axios.get("http://localhost:5000/orders/");
            const ordersData = Array.isArray(res.data.orders) ? res.data.orders : [];
            setOrders(ordersData);
        } catch (err) {
            setAlertMessage("Error fetching orders: " + err.message);
            setShowAlert(true);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchOrders();
    }, [ordersChanged]);

    const handleDeleteClick = (order) => {
        setConfirmDialogData(order);
        setShowConfirmDialog(true);
    };

    const handleDelete = async () => {
        if (confirmDialogData) {
            try {
                await axios.delete(`http://localhost:5000/orders/${confirmDialogData._id}`);
                setAlertMessage("Order deleted successfully!");
                setShowAlert(true);
                setTimeout(() => setShowAlert(false), 3000);
                fetchOrders();
            } catch (err) {
                setAlertMessage("Error deleting order: " + err.message);
                setShowAlert(true);
                setTimeout(() => setShowAlert(false), 3000);
            }
            setShowConfirmDialog(false);
        }
    };

    const handleCancel = () => {
        setShowConfirmDialog(false);
    };

    const filterOrders = orders.filter((order) =>
        order.orderId?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        order.firstName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        order.lastName?.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const generateReport = () => {
        const doc = new jsPDF();
        doc.text("Order Management Report", 14, 16);

        const columns = [
            "First Name", "Last Name", "Email", "Phone Number",
            "Address", "City", "Order Id", "Special Instructions",
            "Pickup Time", "Order Status"
        ];
        const rows = filterOrders.map((order) => [
            order.firstName, order.lastName, order.email,
            order.phoneNumber, order.address, order.city,
            order.orderId, order.specialInstructions,
            order.pickupTime, order.orderStatus
        ]);

        doc.autoTable({
            head: [columns],
            body: rows,
            startY: 22,
        });

        doc.save("Orders_report.pdf");
    };

    return (
        <div style={{ padding: "20px", backgroundColor: "#f3f4f6", minHeight: "100vh" }}>
            <h1 style={{ textAlign: "center", fontSize: "2.25rem", fontWeight: "bold", marginBottom: "1.5rem" }}>
                All Orders
            </h1>

            <div style={{ display: "flex", justifyContent: "center", marginBottom: "20px" }}>
                <SearchBar onSearch={setSearchQuery} />
            </div>

            {loading ? (
                <div style={{ textAlign: "center", padding: "20px" }}>Loading orders...</div>
            ) : (
                <>
                    <table style={{ width: "100%", borderCollapse: "collapse", backgroundColor: "#fff" }}>
                        <thead>
                            <tr>
                                <th>First Name</th>
                                <th>Last Name</th>
                                <th>Email</th>
                                <th>Phone Number</th>
                                <th>Address</th>
                                <th>City</th>
                                <th>Order Id</th>
                                <th>Special Instructions</th>
                                <th>Pickup Time</th>
                                <th>Order Status</th>
                                <th>Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filterOrders.length > 0 ? (
                                filterOrders.map((order) => (
                                    <tr key={order._id}>
                                        <td>{order.firstName}</td>
                                        <td>{order.lastName}</td>
                                        <td>{order.email}</td>
                                        <td>{order.phoneNumber}</td>
                                        <td>{order.address}</td>
                                        <td>{order.city}</td>
                                        <td>{order.orderId}</td>
                                        <td>{order.specialInstructions}</td>
                                        <td>{order.pickupTime}</td>
                                        <td>{order.orderStatus}</td>
                                        <td>
                                            <Link
                                                to={`/update-order/${order._id}`}
                                                style={{ color: "#800000", textDecoration: "none", marginRight: "10px" }}
                                            >
                                                View
                                            </Link>
                                            <button
                                                onClick={() => handleDeleteClick(order)}
                                                style={{
                                                    backgroundColor: "#dc2626",
                                                    color: "#fff",
                                                    padding: "6px 12px",
                                                    borderRadius: "4px",
                                                    border: "none",
                                                    cursor: "pointer",
                                                }}
                                            >
                                                Delete
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan="11" style={{ textAlign: "center", padding: "10px" }}>
                                        No orders available
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>

                    {showAlert && (
                        <div style={{
                            position: 'fixed',
                            top: '20px',
                            left: '50%',
                            transform: 'translateX(-50%)',
                            backgroundColor: 'red',
                            color: 'white',
                            padding: '10px',
                            borderRadius: '5px'
                        }}>
                            {alertMessage}
                        </div>
                    )}

                    {/* Buttons for Generate Report and Back to Home */}
                    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginTop: "20px" }}>
                        <button
                            onClick={generateReport}
                            style={{
                                padding: "12px 20px",
                                backgroundColor: "black",
                                color: "white",
                                border: "none",
                                borderRadius: "5px",
                                cursor: "pointer",
                                fontSize: "16px",
                                width: "100%",
                                maxWidth: "200px",
                                marginBottom: "15px"
                            }}
                        >
                            Generate Report
                        </button>
                        <button
                            onClick={() => navigate("/")}
                            style={{
                                padding: "12px 20px",
                                backgroundColor: "#dc2626",
                                color: "white",
                                border: "none",
                                borderRadius: "5px",
                                cursor: "pointer",
                                fontSize: "16px",
                                width: "100%",
                                maxWidth: "200px",
                            }}
                        >
                            Back to Home
                        </button>
                    </div>
                </>
            )}
        </div>
    );
};

export default AllOrders;
